#include <iostream>
#include <algorithm>
#include <cstdint>

int main() {
    int64_t a[15];
    int64_t i, l, r, x, j, n1, n2;
    x = 0;
    j = 1;
    std::cin >> l >> r;
    for (i = 0; i <= 10; i++) {
        a[i] = 0;
    }
    while (j <= r) {
        i = 10;
        a[i]++;
        while (a[i] > 2) {
            a[i] = 0;
            i--;
            a[i]++;
        }
        j = 0;
        for (i = 1; i <= 10; i++) {
            if (j > 0 && a[i] == 0) {
                break;
            }
            if (a[i] == 1) {
                n1 = 4;
            } else {
                n1 = 0;
            }
            if (a[i] == 2) {
                n2 = 7;
            } else {
                n2 = 0;
            }
            j = j * 10 + n1 + n2;
        }
        if (x == 0 && j >= l) {
            x += j;
        }
        if (i <= 10) {
            continue;
        }
        if (j >= l) {
            x += (std::min(j, r) - l) * j;
            l = j;
        }
    }
    std::cout << x;
    return 0;
}

